import React, { useState } from "react";
import "./index.css";

function App() {

  const [isSignUp, setIsSignUp] = useState(false);

  /* Generate days */
  const days = Array.from({ length: 31 }, (_, i) => i + 1);

  /* Months */
  const months = [
    "January","February","March","April","May","June",
    "July","August","September","October","November","December"
  ];

  /* Years (1900 - current year) */
  const currentYear = new Date().getFullYear();
  const years = [];

  for (let y = currentYear; y >= 1900; y--) {
    years.push(y);
  }

  return (
    <div className="auth-page">
      <div className={`auth-container ${isSignUp ? "signup-mode" : ""}`}>

        {/* LEFT SIDE */}
        <div className="auth-panel brand-panel">
          <div className="brand-content">
            <h1 className="brand-title">RentMate</h1>

            <p className="brand-subtitle">
              {isSignUp
                ? "Already have an account? Sign in and continue exploring rentals."
                : "Sign up now and enjoy our site."}
            </p>

            <button
              className="outline-btn"
              onClick={() => setIsSignUp(!isSignUp)}
            >
              {isSignUp ? "SIGN IN" : "SIGN UP"}
            </button>
          </div>
        </div>

        {/* RIGHT SIDE */}
        <div className="auth-panel form-panel">

          {!isSignUp ? (

            /* LOGIN */
            <div className="form-wrapper">
              <h2>SIGN IN</h2>
              <p className="form-subtext">Sign in with Email & Password</p>

              <div className="form-group">
                <label>Email or Mobile Number</label>
                <input type="text" placeholder="Enter Mobile Number or Email Address"/>
              </div>

              <div className="form-group">
                <label>Password</label>
                <input type="password" placeholder="Password"/>
              </div>

              <p className="forgot-password">Forgot Password?</p>

              <button className="primary-btn">SIGN IN</button>
            </div>

          ) : (

            /* SIGNUP */
            <div className="form-wrapper">

              <h2>SIGN UP</h2>
              <p className="form-subtext">Get started on RentMate</p>

              <div className="row two-cols">
                <div className="form-group">
                  <label>First Name</label>
                  <input type="text" placeholder="First name"/>
                </div>

                <div className="form-group">
                  <label>Surname</label>
                  <input type="text" placeholder="Surname"/>
                </div>
              </div>

              <label className="section-label">Date of Birth</label>

              <div className="row three-cols">

                {/* DAY */}
                <select>
                  <option>Day</option>
                  {days.map(day => (
                    <option key={day} value={day}>{day}</option>
                  ))}
                </select>

                {/* MONTH */}
                <select>
                  <option>Month</option>
                  {months.map((month, index) => (
                    <option key={index} value={month}>{month}</option>
                  ))}
                </select>

                {/* YEAR */}
                <select>
                  <option>Year</option>
                  {years.map(year => (
                    <option key={year} value={year}>{year}</option>
                  ))}
                </select>

              </div>

              <div className="form-group">
                <label>Gender</label>
                <select>
                  <option>Select your gender</option>
                  <option>Male</option>
                  <option>Female</option>
                  <option>Prefer not to say</option>
                </select>
              </div>

              <div className="form-group">
                <label>Email or Mobile Number</label>
                <input type="text" placeholder="Enter Mobile Number or Email Address"/>
              </div>

              <div className="form-group">
                <label>Password</label>
                <input type="password" placeholder="Enter Password"/>
              </div>

              <button className="primary-btn">
                CREATE ACCOUNT
              </button>

            </div>

          )}

        </div>
      </div>
    </div>
  );
}

export default App;
